CREATE TABLE "AdventureMap" ("id" TEXT NOT NULL PRIMARY KEY, "ownerId" TEXT, "name" TEXT NOT NULL, "campaignId" TEXT, "version" INTEGER NOT NULL DEFAULT 1, "data" JSONB NOT NULL, "archived" BOOLEAN NOT NULL DEFAULT false, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL); CREATE INDEX "AdventureMap_ownerId_archived_idx" ON "AdventureMap"("ownerId", "archived");
